/// The gallery's example of `Sheet`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_description = args.text("description");
        let arg_side = match args.choice("side") {
            "Left" => Side::Left,
            _ => Side::Right,
        };
        let arg_width = args.number("width") as f32;

        let open = State::new(args.bool("open"));
        let show = open.clone();
        let active = State::new(args.bool("active"));
        VStack::new((
            Button::new("Open filters").style(ButtonStyle::Secondary).on_click(move || show.set(true)),
            {
                let mut it = Sheet::new(open.binding(), "Filters")
                    .content(Toggle::new(active.binding()).label("Only active accounts"));
                it = it.description(arg_description.clone());
                it = it.side(arg_side.clone());
                it = it.width(arg_width);
                it
            },
        ))
    })
}

impl ComponentBook for Sheet {
    fn book() -> Meta {
        Meta::new("Overlays/Sheet", render)
            .summary("Panel that slides over the UI from one edge.")
            .arg(ArgType::text("description", "Narrow down the accounts shown."))
            .arg(ArgType::choice("side", &["Left", "Right"], "Right"))
            .arg(ArgType::number("width", 400.0, 0.0, 1600.0, 1.0))
            .arg(ArgType::bool("open", false).description("How the example starts."))
            .arg(ArgType::bool("active", true).description("How the example starts."))
            .story("Example", Args::new())
            .story("Side: Left", Args::new().with("side", ArgValue::choice("Left")))
            .story("Open", Args::new().with("open", true))
    }
}
